// Bluetooth ile LED: telefondan "ac" / "kapat" komutu.
// Telefona "Serial Bluetooth Terminal" gibi bir uygulama kur ve KendinYap-LED cihazına bağlan.
#include <BluetoothSerial.h>

const int LED_PIN = 2;
BluetoothSerial SerialBT;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  SerialBT.begin("KendinYap-LED");
  Serial.println("Bluetooth hazir: KendinYap-LED");
}

void loop() {
  if (SerialBT.available()) {
    String komut = SerialBT.readStringUntil('\n');
    komut.trim();
    komut.toLowerCase();
    Serial.println("Komut: " + komut);
    if (komut == "ac") {
      digitalWrite(LED_PIN, HIGH);
      SerialBT.println("LED acildi");
    } else if (komut == "kapat") {
      digitalWrite(LED_PIN, LOW);
      SerialBT.println("LED kapandi");
    } else {
      SerialBT.println("Komutlar: ac, kapat");
    }
  }
  delay(20);
}
